examples.template:
Column(
    modifier = Modifier
        .fillMaxWidth()
        .border(MonarchTheme.spacing.px, MonarchTheme.colors.borderDefault, MonarchTheme.shapes.md)
        .padding(MonarchTheme.spacing.space2),
    verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
) {
    MonarchEditorToolbar(
        onAction = { tool -> active = if (tool in active) active - tool else active + tool },
        groups = listOf(
            listOf(MonarchEditorTool.Undo, MonarchEditorTool.Redo),
            listOf(MonarchEditorTool.Paragraph, MonarchEditorTool.heading(1), MonarchEditorTool.heading(2), MonarchEditorTool.heading(3)),
            listOf(MonarchEditorTool.Bold, MonarchEditorTool.Italic, MonarchEditorTool.Strikethrough, MonarchEditorTool.Code, MonarchEditorTool.Link),
            listOf(MonarchEditorTool.BulletList, MonarchEditorTool.OrderedList),
            listOf(MonarchEditorTool.Blockquote, MonarchEditorTool.CodeBlock),
        ),
        active = active,
        disabled = setOf(MonarchEditorTool.{{disabledTool|pascal}}),
        onLink = { address ->
            active = if (address == null) active - MonarchEditorTool.Link else active + MonarchEditorTool.Link
        },
    )
    MonarchText(text = {{heading}}, style = MonarchTextStyle.Heading)
    MonarchText(
        text = buildAnnotatedString {
            append({{paragraph.before}})
            withStyle(SpanStyle(fontWeight = FontWeight.Bold)) { append({{paragraph.bold}}) }
            append({{paragraph.after}})
        },
    )
    MonarchText(text = "\u2022 " + {{bullets.0}})
    MonarchText(text = "\u2022 " + {{bullets.1}})
}

